// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // fuzz parameters: caller address and an arbitrary uint to ensure fuzzer explores combos
    function testFuzz_property(address caller, uint256 dummy) public {
        // Keep domain wide: ensure caller is not zero address to make call sensible
        vm.assume(caller != address(0));

        // construct an empty address[] to exercise the empty-array boundary
        address[] memory tos = new address[](0);

        // perform the call and observe whether it reverted
        bool ok;
        vm.prank(caller);
        try c.transfer(caller, address(this), tos, 0) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: reference contract always reverts on empty _tos (require > 0),
        // so ok must be false for the correct contract; the mutant that changes the
        // require to >= 0 will make ok true for some inputs (empty array) — assert that
        // the call reverted (ok == false)
        assertTrue(!ok);
    }
}
